#undef TEMPO

void theme::tick() {
	if (m_stopped || m_paused)
		return;

	for (int i = 0; i < 4; ++i) {
		if (notes[m_rows[i]][i].isValid()) {
			songnote &note = notes[m_rows[i]][i];
			note.tick();
			if (note.finishedPlaying()) {
				++m_rows[i];
				while (notes[m_rows[i]][i].isValid() && notes[m_rows[i]][i].isPadNote())
					++m_rows[i];
				if (!notes[m_rows[i]][i].isValid())
					m_rows[i] = 0;
			}
		}
	}
}

void theme::stop() {
	m_stopped = true;
	for (int i = 0; i < 4; ++i)
		m_rows[i] = 0;
	for (int x = 0; x < 4; ++x)
		for (int y = 0; notes[y][x].isValid(); ++y)
			notes[y][x].stop();
	Mix_HaltChannel(-1);
}

void theme::resume() {
	m_stopped = false;
}

void theme::toggle() {
	if (m_stopped)
		resume();
	else
		stop();
}

void theme::set_paused(bool paused) {
	m_paused = paused;
}
